def is_woodall(n):
    if n <= 1:
        return False

    # Add 1 to n and divide by 2 until it's odd
    m = n + 1
    while m % 2 == 0:
        m //= 2

    # Check if the resulting number is prime
    if m <= 1:
        return False

    # Trial division for primality
    d = 2
    while d * d <= m:
        if m % d == 0:
            return False
        d += 1

    return True
```

