def bell_number(n):
    if n == 0:
        return 1
    # Bell triangle (Aitken's array)
    # We need n+1 rows to compute the nth Bell number
    triangle = []
    for i in range(n + 1):
        row = [0] * (i + 1)
        if i == 0:
            row[0] = 1
        else:
            row[0] = triangle[-1][-1]
            for j in range(1, i + 1):
                row[j] = triangle[-1][j - 1] + row[j - 1]
        triangle.append(row)

    return triangle[-1][0]
```

