def is_undulating(n):
    s = str(n)
    if len(s) <= 2:
        return False

    # An undulating number must start with a non-zero digit (handled by int conversion)
    # Pattern: ABA... where A != B. 
    # It must alternate: index 0 == 2 == 4..., and index 1 == 3 == 5...
    # AND index 0 must not equal index 1.

    first_digit = s[0]
    second_digit = s[1]

    if first_digit == second_digit:
        return False

    # Check even positions
    for i in range(2, len(s), 2):
        if s[i] != first_digit:
            return False

    # Check odd positions
    for i in range(3, len(s), 2):
        if s[i] != second_digit:
            return False

    return True
```

