import math

def div_sum(n):
    if n <= 1:
        return n

    total = 1  # 1 is always a divisor for n > 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            total += i
            if i != n // i:  # Avoid double counting for perfect squares
                total += n // i
        i += 1
    return total

def are_equivalent(num1, num2):
    return div_sum(num1) == div_sum(num2)
```

