def is_majority(arr, n, x):
    def binary_search_left(arr, low, high, x):
        if high >= low:
            mid = (low + high) // 2
            if arr[mid] == x:
                if mid == 0 or arr[mid - 1] != x:
                    return mid
                else:
                    return binary_search_left(arr, low, mid - 1, x)
            elif arr[mid] < x:
                return binary_search_left(arr, mid + 1, high, x)
            else:
                return binary_search_left(arr, low, mid - 1, x)
        return -1

    def binary_search_right(arr, low, high, x):
        if high >= low:
            mid = (low + high) // 2
            if arr[mid] == x:
                if mid == n - 1 or arr[mid + 1] != x:
                    return mid
                else:
                    return binary_search_right(arr, mid + 1, high, x)
            elif arr[mid] < x:
                return binary_search_right(arr, mid + 1, high, x)
            else:
                return binary_search_right(arr, low, mid - 1, x)
        return -1

    start_index = binary_search_left(arr, 0, n - 1, x)
    if start_index == -1:
        return False

    end_index = binary_search_right(arr, 0, n - 1, x)
    count = end_index - start_index + 1

    return count > n // 2
```

