def binary_search_first(arr, low, high, x):
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            result = mid
            high = mid - 1  # Continue searching in the left half
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return result
