def max_sum(arr): 
    n = len(arr)
    if n == 0:
        return 0

    # LIS[i]: Maximum sum of increasing subsequence ending at index i
    LIS = [0] * n
    # LDS[i]: Maximum sum of decreasing subsequence starting at index i
    LDS = [0] * n

    # Calculate LIS
    for i in range(n):
        LIS[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                if LIS[j] + arr[i] > LIS[i]:
                    LIS[i] = LIS[j] + arr[i]

    # Calculate LDS (by reversing the array logic)
    for i in range(n):
        LDS[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                if LDS[j] + arr[i] > LDS[i]:
                    LDS[i] = LDS[j] + arr[i]

    # Find maximum bitonic sum
    max_total = 0
    for i in range(n):
        current_sum = LIS[i] + LDS[i] - arr[i]
        if current_sum > max_total:
            max_total = current_sum

    return max_total
