def count_no_of_ways(n, k):
    if n == 0:
        return 0
    if n == 1:
        return k
    if n == 2:
        return k * k

    same = k      # Ways where the current post is same color as previous
    diff = k * (k - 1)  # Ways where the current post is different color

    for _ in range(3, n + 1):
        new_same = diff       # To be same as current, previous must be different
        new_diff = (same + diff) * (k - 1)
        same, diff = new_same, new_diff

    return (same + diff) % 1000000007
