def sumofFactors(n):
    if n % 2 != 0:
        return 0

    res = 1
    d = 2
    while d * d <= n:
        if n % d == 0:
            count = 0
            while n % d == 0:
                n //= d
                count += 1
            # Sum of powers: 1 + d + d^2 + ... + d^count
            power_sum = (d**(count+1) - 1) // (d - 1)
            res *= power_sum
        d += 1
    if n > 1:
        res *= (n + 1)

    return res
```

