        if n % divisor == 0:
            exponent = 0
            sum_powers = 1
            while n % divisor == 0:
                exponent += 1
                n //= divisor
                sum_powers += divisor ** exponent
            result *= sum_powers
        divisor += 1

    if n > 1:
        result *= (1 + n)

