def is_majority(arr, n, x):
    # Find the first occurrence of x
    left, right = 0, n - 1
    first = -1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            if mid == 0 or arr[mid - 1] != x:
                first = mid
                break
            right = mid - 1
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    if first == -1:
        return False

    # Check the element at index first + n//2
    # If this index is out of bounds, it's not a majority
    if first + n // 2 >= n:
        return False

    return arr[first + n // 2] == x
```

