def is_majority(arr, n, x):
    # If the array is empty, it cannot have a majority
    if n == 0:
        return False

    # Find the first occurrence of x using binary search
    low, high = 0, n - 1
    first = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            first = mid
            high = mid - 1
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1

    if first == -1:
        return False

    # Check if the element at index (first + n/2) is still x
    # This works because the array is sorted. If x appears more than n/2 times,
    # it must span the middle of the array.
    if first + (n // 2) < n and arr[first + (n // 2)] == x:
        return True
    else:
        return False
