def get_max_sum(n):
    memo = {}

    def f(x):
        if x == 0:
            return 0
        if x == 1:
            return 1
        if x in memo:
            return memo[x]

        # Option 1: take x as is
        option1 = x

        # Option 2: use the recursive formula
        # Note: integer division // is used for n/2, n/3, etc.
        option2 = f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5)

        result = max(option1, option2)
        memo[x] = result
        return result

    return f(n)
```

