        return 0
    if n == 0:
        return 0
    if n == 1:
        return 2
    if n == 2:
        return 3

    p = [0] * (n + 1)
    p[0] = 0
    p[1] = 2
    p[2] = 3

    for i in range(3, n + 1):
        p[i] = p[i-2] + p[i-3]

    return sum(p[:n+1])
