def cal_sum(n):
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    # Base cases for Perrin numbers: P(0)=3, P(1)=0, P(2)=2
    if n == 0:
        return 3
    if n == 1:
        return 0
    if n == 2:
        return 2

    # Generate Perrin numbers up to n
    p = [0] * (n + 1)
    p[0] = 3
    p[1] = 0
    p[2] = 2

    for i in range(3, n + 1):
        p[i] = p[i-2] + p[i-3]

    return sum(p)
```

