def search(arr):
    if not arr or arr[0] != arr[-1]:
        return 1 if arr[0] != arr[1] else arr[-1]

    left, right = 0, len(arr) - 1

    while left < right:
        mid = (left + right) // 2

        # Check if mid is even or odd to determine the pair structure
        if mid % 2 == 1:
            # mid is odd, so pairs are (mid-1, mid), (mid+1, mid+2), etc.
            if arr[mid] == arr[mid - 1]:
                # The single element is to the right
                left = mid + 1
            else:
                # The single element is to the left (including mid)
                right = mid
        else:
            # mid is even, so pairs are (mid, mid+1), (mid+2, mid+3), etc.
            if arr[mid] == arr[mid + 1]:
                # The single element is to the right
                left = mid + 2
            else:
                # The single element is to the left (including mid)
                right = mid

    return arr[left]
```

