import math

def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None
    if a == 0:
        return (0, n // b) if n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None

    g = math.gcd(a, b)
    if n % g != 0:
        return None

    # Use extended Euclidean algorithm to find x0, y0 such that ax0 + by0 = g
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        g, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return g, x, y

    g, x0, y0 = extended_gcd(a, b)
    # Scale the solution to match n
    x = x0 * (n // g)
    y = y0 * (n // g)

    return (x, y)
```

