import math

def find_solution(a, b, n):
    """
    Returns a tuple (x, y) of integers such that ax + by = n,
    or None if no such integers exist.

    Uses the Extended Euclidean Algorithm to solve the linear Diophantine equation.
    """
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return None if n % b != 0 else (0, n // b)
    if b == 0:
        return None if n % a != 0 else (n // a, 0)

    gcd, x0, y0 = extended_gcd(a, b)

    if n % gcd != 0:
        return None

    # Scale the solution
    factor = n // gcd
    x = x0 * factor
    y = y0 * factor

    return (x, y)
```

