def get_max_sum(n: int) -> int:
    if n <= 0:
        return 0

    # Memoization dictionary to store results of subproblems
    memo = {0: 0, 1: 1}

    def helper(x):
        if x in memo:
            return memo[x]

        # Calculate the sum of recursive calls
        recursive_sum = helper(x // 2) + helper(x // 3) + helper(x // 4) + helper(x // 5)

        # Store the maximum of the recursive sum and x itself
        result = max(recursive_sum, x)
        memo[x] = result
        return result

    return helper(n)
```

