def cal_sum(n):
    if n < 0:
        return 0
    if n == 0:
        return 0
    if n == 1:
        return 2

    # Perrin sequence: P(0)=3, P(1)=0, P(2)=2, P(n)=P(n-2)+P(n-3)
    p = [3, 0, 2]
    for i in range(3, n + 1):
        p.append(p[i-2] + p[i-3])

    return sum(p[:n+1])
```

